-- ============================================================================
-- 0045_historico_2025_diario.sql — Historia REAL día a día de 2025
-- ============================================================================
-- POR QUÉ: al importar 2025 se cargó el TOTAL de cada mes en una sola fecha
-- (15-nov, 15-dic, y 15-oct de Danitza/Joselyn), porque la fuente usada fue la
-- hoja "Gratificaciones Dic 2025" que traía totales mensuales. Eso dejaba en el
-- Perfil "días" imposibles de 125 h, 181 h y hasta 270 h.
--
-- El detalle diario SÍ existía: el CSV "Dynamic Time 2025" (17,817 marcas).
-- VERIFICADO antes de escribir esto: al sumar el CSV por persona y mes, 13 de 14
-- totales coinciden AL CENTÉSIMO con lo ya cargado. La única diferencia es
-- Chiara diciembre: el CSV dice 228.39 h y se había cargado 198.12 h (−30.27 h),
-- o sea la hoja de gratificaciones tenía menos horas de las que ella marcó.
-- Por eso importar es seguro: no mueve la plata de nadie, salvo corregir a Chiara.
--
-- Datos: 1,427 días de las 7 personas que continúan, enero a diciembre 2025.
-- Cero marcas impares en el origen (toda entrada tiene su salida).
-- Idempotente: re-ejecutable sin duplicar.
-- ============================================================================

-- 1) Extender el tramo de salario 2025 hasta su primera jornada, para que NINGÚN
--    día importado quede sin salario (la verificación de 0033 exige que sea 0).
--    Decisión de Felipe (2026-07-20): mismo salario durante todo 2025.
update asignaciones_salario a set vigente_desde = date '2025-01-02'
  from personas pe where pe.id = a.persona_id and pe.nombres = 'Carlos'
    and a.nota = 'historico 2025 (CTS)' and a.vigente_desde > date '2025-01-02';
update asignaciones_salario a set vigente_desde = date '2025-05-15'
  from personas pe where pe.id = a.persona_id and pe.nombres = 'Chiara'
    and a.nota = 'historico 2025 (CTS)' and a.vigente_desde > date '2025-05-15';
update asignaciones_salario a set vigente_desde = date '2025-09-30'
  from personas pe where pe.id = a.persona_id and pe.nombres = 'Danitza'
    and a.nota = 'historico 2025 (CTS)' and a.vigente_desde > date '2025-09-30';
update asignaciones_salario a set vigente_desde = date '2025-01-02'
  from personas pe where pe.id = a.persona_id and pe.nombres = 'Janis'
    and a.nota = 'historico 2025 (CTS)' and a.vigente_desde > date '2025-01-02';
update asignaciones_salario a set vigente_desde = date '2025-10-11'
  from personas pe where pe.id = a.persona_id and pe.nombres = 'Joselyn'
    and a.nota = 'historico 2025 (CTS)' and a.vigente_desde > date '2025-10-11';
update asignaciones_salario a set vigente_desde = date '2025-03-13'
  from personas pe where pe.id = a.persona_id and pe.nombres = 'Melany'
    and a.nota = 'historico 2025 (CTS)' and a.vigente_desde > date '2025-03-13';
update asignaciones_salario a set vigente_desde = date '2025-01-28'
  from personas pe where pe.id = a.persona_id and pe.nombres = 'Sandra'
    and a.nota = 'historico 2025 (CTS)' and a.vigente_desde > date '2025-01-28';

-- 2) Borrar los AGREGADOS de 2025 (el total de un mes guardado en una fecha).
--    Regla: más de 24 h en un día es físicamente imposible ⇒ es un agregado.
--    Respeta el único día real raro (Danitza 30-sep, 5.59 h). Es indispensable:
--    Janis no marcó ni el 15-nov ni el 15-dic, así que sin este borrado sus
--    agregados sobrevivirían al upsert y sus horas se contarían DOS VECES.
delete from jornadas j
using personas pe
where pe.id = j.persona_id
  and pe.nombres in ('Sandra','Janis','Melany','Chiara','Carlos','Danitza','Joselyn')
  and j.fecha >= date '2025-01-01' and j.fecha < date '2026-01-01'
  and j.horas_trabajadas > 24;

