insert into jornadas (persona_id, fecha, sede_id, horas_trabajadas, entrada_ts, salida_final_ts, estado)
select pe.id, d.fecha, pe.sede_base_id, d.horas, d.ent, d.sal, 'cerrada'::estado_jornada
from datos d
join personas pe on pe.nombres = d.nombre
on conflict (persona_id, fecha) do update
  set horas_trabajadas = excluded.horas_trabajadas,
      entrada_ts       = excluded.entrada_ts,
      salida_final_ts  = excluded.salida_final_ts,
      estado           = 'cerrada';

-- 4) Verificación: ningún día de 2025 puede quedar sin salario, y ya no debe
--    existir ninguna jornada con más de 24 h.
select p.nombres,
       (select count(*) from jornadas j where j.persona_id=p.id and j.fecha<date '2026-01-01') as dias_2025,
       (select round(sum(j.horas_trabajadas)::numeric,2) from jornadas j where j.persona_id=p.id and j.fecha<date '2026-01-01') as horas_2025,
       (select count(*) from jornadas j where j.persona_id=p.id and j.fecha<date '2026-01-01' and j.horas_trabajadas>24) as agregados_DEBE_SER_0,
       (select count(*) from jornadas j where j.persona_id=p.id and j.fecha<date '2026-01-01'
          and not exists (select 1 from asignaciones_salario a where a.persona_id=j.persona_id
            and j.fecha>=a.vigente_desde and j.fecha<=coalesce(a.vigente_hasta,'infinity'::date))) as sin_salario_DEBE_SER_0
from personas p
where p.nombres in ('Sandra','Janis','Melany','Chiara','Carlos','Danitza','Joselyn')
order by p.nombres;
